package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.junit.jupiter.api.Test;

class LmdbNativeValueCodecPositionTest {

	@Test
	void objectChurnCannotEvictTheSubjectBank() throws Exception {
		LmdbNativeValueCodec codec = new LmdbNativeValueCodec(null);
		long subject = integerId(9000);
		Object original = codec.decode(subject, 1);
		for (int i = 1; i <= 4096; i++) {
			codec.decode(integerId(i), 4);
		}
		assertThat(codec.decode(subject, 1)).isSameAs(original);
		assertThat(codec.decode(subject, 15)).isSameAs(original);
	}

	@Test
	void wholeBudgetIsSplitWithoutRoundingUp() throws Exception {
		LmdbNativeValueCodec codec = new LmdbNativeValueCodec(null);
		assertThat(codec.cacheBankCapacity(0)).isEqualTo(410);
		assertThat(codec.cacheBankCapacity(1)).isEqualTo(410);
		assertThat(codec.cacheBankCapacity(2)).isEqualTo(410);
		assertThat(codec.cacheBankCapacity(3)).isEqualTo(409);
		assertThat(codec.cacheBankCapacity(4)).isEqualTo(409);
	}

	@Test
	void zeroBanksBypassAndTinyBanksRemainConcurrent() throws Exception {
		LmdbNativeValueCodec codec = new LmdbNativeValueCodec(null, 2);
		assertThat(codec.cacheBankCapacity(0)).isEqualTo(1);
		assertThat(codec.cacheBankCapacity(1)).isEqualTo(1);
		assertThat(codec.cacheBankCapacity(2)).isZero();
		long id = integerId(17);
		assertThat(codec.decode(id, 4)).isNotSameAs(codec.decode(id, 4));
		ExecutorService pool = Executors.newFixedThreadPool(4);
		try {
			List<Future<?>> runs = new ArrayList<>();
			for (int worker = 0; worker < 4; worker++) {
				final int offset = worker;
				runs.add(pool.submit(() -> {
					for (int i = 1; i <= 20_000; i++) {
						long value = i + offset;
						assertThat(codec.decode(integerId(value), i % 16).label()).isEqualTo(Long.toString(value));
					}
				}));
			}
			for (Future<?> run : runs) {
				run.get();
			}
		} finally {
			pool.shutdownNow();
		}
	}

	private static long integerId(long value) {
		return ValueIds.createId(ValueIds.T_INTEGER, (value << 1) ^ (value >> 63));
	}
}
